def expected_time(position, failed_tricks):
    if position >= n:
        return n

    current_time = position
    min_time = float('inf')

    for t, p, d in tricks:
        if t > position:
            # No trick at this position, continue to the next
            continue

        if t == position:
            # Trick at this position
            success_time = expected_time(t + 1, failed_tricks)
            failure_time = expected_time(t + 1, failed_tricks + 1) + d
            current_time = p * success_time + (1 - p) * failure_time

        if current_time >= r:
            break

    # Option to reset the game
    reset_time = n + failed_tricks * d
    min_time = min(min_time, current_time, reset_time)

    return min_time

